CREATE TABLE `CookieConsentSettings` (`id` VARCHAR(191) NOT NULL, `tenantId` INTEGER NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT false, `consentVersion` VARCHAR(191) NOT NULL DEFAULT '1', `bannerTitle` VARCHAR(191) NOT NULL DEFAULT 'We use cookies', `bannerDescription` TEXT NOT NULL, `position` VARCHAR(191) NOT NULL DEFAULT 'bottom', `acceptAllText` VARCHAR(191) NOT NULL DEFAULT 'Accept All', `rejectAllText` VARCHAR(191) NOT NULL DEFAULT 'Reject All', `customizeText` VARCHAR(191) NOT NULL DEFAULT 'Customize', `privacyPolicyUrl` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `CookieConsentSettings_tenantId_key` (`tenantId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CookieCategory` (`id` VARCHAR(191) NOT NULL, `tenantId` INTEGER NOT NULL, `name` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `description` TEXT NULL, `required` BOOLEAN NOT NULL DEFAULT false, `enabled` BOOLEAN NOT NULL DEFAULT true, `sortOrder` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `CookieCategory_tenantId_slug_key` (`tenantId`, `slug`), INDEX `CookieCategory_tenantId_sortOrder_idx` (`tenantId`, `sortOrder`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CookieDefinition` (`id` VARCHAR(191) NOT NULL, `tenantId` INTEGER NOT NULL, `categoryId` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `provider` VARCHAR(191) NULL, `description` TEXT NULL, `duration` VARCHAR(191) NULL, `pattern` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `CookieDefinition_tenantId_categoryId_idx` (`tenantId`, `categoryId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `CookieConsentSettings` ADD CONSTRAINT `CookieConsentSettings_tenantId_fkey` FOREIGN KEY (`tenantId`) REFERENCES `tenant`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `CookieCategory` ADD CONSTRAINT `CookieCategory_tenantId_fkey` FOREIGN KEY (`tenantId`) REFERENCES `tenant`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `CookieDefinition` ADD CONSTRAINT `CookieDefinition_tenantId_fkey` FOREIGN KEY (`tenantId`) REFERENCES `tenant`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
